#include <iostream>
struct Rate {int multiplier;int apply(int n)const{return multiplier*n;}};
class Report {Rate rate_;public:explicit Report(Rate r):rate_(r){}int total(int n)const{return rate_.apply(n);}};
int main(){Report r{Rate{3}};std::cout<<r.total(4)<<'\n';}

#include <iostream>
#include <memory>
struct Rule {virtual int apply(int)const=0;virtual ~Rule()=default;};
struct Double final:Rule {int apply(int n)const override{return n*2;}};
int main(){std::unique_ptr<Rule> r=std::make_unique<Double>();std::cout<<r->apply(4)<<' ';
 std::cout<<(dynamic_cast<Double*>(r.get())!=nullptr)<<'\n';}

